public class GreeterTest {
    static int failures = 0;

    static void check(String label, Object expected, Object actual) {
        if (java.util.Objects.equals(expected, actual)) {
            System.out.println("PASS  " + label);
        } else {
            System.out.println("FAIL  " + label + " -- expected " + expected + " but got " + actual);
            failures++;
        }
    }

    public static void main(String[] args) {
        check("named user", "Hello, ADA!", Greeter.describeUser(java.util.Optional.of("ada")));
        check("mixed case name", "Hello, BOB!", Greeter.describeUser(java.util.Optional.of("Bob")));
        check("single letter name", "Hello, X!", Greeter.describeUser(java.util.Optional.of("x")));
        check("already uppercase", "Hello, GRACE!", Greeter.describeUser(java.util.Optional.of("GRACE")));
        check("empty optional", "Hello, guest!", Greeter.describeUser(java.util.Optional.empty()));
        check("ofNullable with null", "Hello, guest!", Greeter.describeUser(java.util.Optional.ofNullable(null)));
        if (failures > 0) {
            System.out.println(failures + " test(s) failed.");
            System.exit(1);
        }
        System.out.println("ALL TESTS PASSED");
    }
}

